// Anthropic Messages API wrapper — used by both the "Build with Claude AI"
// BYOK feature and the live-chat agent (lib/kb-llm.ts). Built on the official
// @anthropic-ai/sdk rather than raw fetch. Every export below (types,
// function names, signatures, thrown-error shape) is unchanged from the prior
// fetch-based version, so no caller needed to change.

import Anthropic from "@anthropic-ai/sdk";
import { decryptSecret } from "./crypto-box";

const MODEL = "claude-opus-4-8";

/** One client per API key — callers pass a different key per request (BYOK),
 *  so this avoids constructing a new client (and re-validating env) on every
 *  call within a hot loop while still never caching across different keys. */
const clients = new Map<string, Anthropic>();
function clientFor(apiKey: string): Anthropic {
  let c = clients.get(apiKey);
  if (!c) {
    c = new Anthropic({ apiKey });
    clients.set(apiKey, c);
  }
  return c;
}

/** Rethrow SDK errors in the same `Error` shape callers already handle
 *  (they only ever read `.message`, never match on it structurally). */
function wrapApiError(e: unknown): Error {
  if (e instanceof Anthropic.APIError) {
    const detail = typeof e.error === "object" ? JSON.stringify(e.error) : String(e.message);
    return new Error(`Anthropic API ${e.status}: ${detail.slice(0, 500)}`);
  }
  return e instanceof Error ? e : new Error(String(e));
}

/** Content block shapes accepted by the Messages API. `content` may be a plain
 *  string, or an array mixing text and (for vision) base64 image blocks. */
export type ClaudeTextBlock = { type: "text"; text: string };
export type ClaudeImageBlock = {
  type: "image";
  source: { type: "base64"; media_type: string; data: string };
};
export type ClaudeContent = string | Array<ClaudeTextBlock | ClaudeImageBlock>;
export type ClaudeMessage = { role: "user" | "assistant"; content: ClaudeContent };

/** True when an optional platform-wide fallback key is configured. */
export function platformKeyConfigured(): boolean {
  return Boolean(process.env.ANTHROPIC_API_KEY && process.env.ANTHROPIC_API_KEY.trim());
}

/** Deprecated alias kept for backwards compatibility. */
export function anthropicConfigured(): boolean {
  return platformKeyConfigured();
}

/**
 * Resolve the effective key for a user: their own decrypted BYOK key if present,
 * otherwise the optional platform-wide ANTHROPIC_API_KEY. Returns null if neither
 * is available. Never throws on a bad/absent stored key (decryptSecret returns null).
 */
export function effectiveKeyFor(
  user: { anthropicKeyEnc?: string | null } | null | undefined
): string | null {
  const own = decryptSecret(user?.anthropicKeyEnc ?? null);
  if (own && own.trim()) return own.trim();
  const platform = process.env.ANTHROPIC_API_KEY;
  return platform && platform.trim() ? platform.trim() : null;
}

/**
 * Send a chat turn to Claude and return the concatenated text of the reply.
 * The caller supplies the API key (the build owner's effective key).
 * Throws when the key is missing or the API returns a non-2xx response.
 */
export async function askClaude(
  apiKey: string,
  messages: ClaudeMessage[],
  system: string,
  opts: {
    maxTokens?: number;
    timeoutMs?: number;
    model?: string;
    /** Mark the system prompt as an ephemeral prompt-cache breakpoint. Opt-in
     *  (default off) because this function is shared by many one-shot callers
     *  (Build with AI planning, marketing studio, ...) whose system prompt is
     *  never reused — caching a prompt that's only sent once adds a small
     *  write premium for zero benefit. Only pass true from a caller whose
     *  system prompt is IDENTICAL across repeated calls (e.g. the chat
     *  agent's round-cap fallback, which reuses the same bot config every
     *  turn of every conversation). */
    cacheSystem?: boolean;
  } = {}
): Promise<string> {
  if (!apiKey) throw new Error("No Anthropic API key available");

  let data: Anthropic.Message;
  try {
    data = await clientFor(apiKey).messages.create(
      {
        model: opts.model ?? MODEL,
        max_tokens: opts.maxTokens ?? 1024,
        system: opts.cacheSystem
          ? ([{ type: "text", text: system, cache_control: { type: "ephemeral" } }] as Anthropic.TextBlockParam[])
          : system,
        messages: messages as Anthropic.MessageParam[],
      },
      { timeout: opts.timeoutMs ?? 60_000 }
    );
  } catch (e) {
    throw wrapApiError(e);
  }

  return data.content
    .filter((b): b is Anthropic.TextBlock => b.type === "text")
    .map((b) => b.text)
    .join("")
    .trim();
}

/** A tool the model can call. `input_schema` is a JSON Schema object. */
export type ClaudeToolDef = {
  name: string;
  description: string;
  input_schema: Record<string, unknown>;
};

type AnyBlock = { type: string; text?: string; id?: string; name?: string; input?: unknown };
type AnyMsg = { role: "user" | "assistant"; content: unknown };

/**
 * Agentic Messages call: give the model tools, run the look-up→reason loop
 * (execute each tool_use, feed the result back) until it produces a final
 * answer or the round cap is hit. `execTool` runs YOUR scoped, read-only tool
 * and returns a string for the model. Returns the model's final text.
 */
export async function askClaudeWithTools(
  apiKey: string,
  opts: {
    system: string;
    messages: ClaudeMessage[];
    tools: ClaudeToolDef[];
    execTool: (name: string, input: unknown) => Promise<string>;
    model?: string;
    maxTokens?: number;
    timeoutMs?: number;
    maxRounds?: number;
    /** Optional progress hook: called with a tool's name right before it runs, so
     *  a caller can surface a live "thinking" step to the end user. Fully
     *  optional and side-effect-free from this function's point of view — every
     *  existing caller that omits it behaves exactly as before. */
    onStep?: (toolName: string) => void;
  },
): Promise<string> {
  if (!apiKey) throw new Error("No Anthropic API key available");
  const msgs: AnyMsg[] = [...(opts.messages as AnyMsg[])];
  const rounds = opts.maxRounds ?? 4;
  const client = clientFor(apiKey);

  // Prompt caching: the system prompt and tool defs are IDENTICAL across every
  // turn of every conversation for a given bot config, yet were being resent
  // uncached on every single API call — for a long system prompt (KB_SYSTEM is
  // 700+ lines) that's the dominant cost of a input-token-heavy agent like the
  // live-chat bot. Marking a cache_control breakpoint on the system block and
  // on the last tool caches everything up to each point (system, then
  // system+tools) so a cache HIT only costs ~10% of a fresh read on every turn
  // after the first — no behavior change, pure cost/latency win.
  const cachedSystem: Anthropic.TextBlockParam[] = [
    { type: "text", text: opts.system, cache_control: { type: "ephemeral" } },
  ];
  const cachedTools = opts.tools.length
    ? opts.tools.map((t, i) =>
        i === opts.tools.length - 1 ? { ...t, cache_control: { type: "ephemeral" as const } } : t
      )
    : opts.tools;

  for (let i = 0; i < rounds; i++) {
    let data: Anthropic.Message;
    try {
      data = await client.messages.create(
        {
          model: opts.model ?? MODEL,
          max_tokens: opts.maxTokens ?? 600,
          system: cachedSystem,
          tools: cachedTools as Anthropic.Tool[],
          messages: msgs as Anthropic.MessageParam[],
        },
        { timeout: opts.timeoutMs ?? 26_000 }
      );
    } catch (e) {
      throw wrapApiError(e);
    }
    const content = data.content as AnyBlock[];

    if (data.stop_reason !== "tool_use") {
      return content
        .filter((b) => b.type === "text" && typeof b.text === "string")
        .map((b) => b.text as string)
        .join("")
        .trim();
    }

    // Execute every requested tool, then feed all results back in one user turn.
    msgs.push({ role: "assistant", content });
    const toolResults: Array<{ type: "tool_result"; tool_use_id: string; content: string }> = [];
    for (const block of content) {
      if (block.type === "tool_use" && block.id && block.name) {
        let out: string;
        try {
          opts.onStep?.(block.name);
          out = await opts.execTool(block.name, block.input);
        } catch (e) {
          out = `Error running ${block.name}: ${e instanceof Error ? e.message : "failed"}`;
        }
        toolResults.push({ type: "tool_result", tool_use_id: block.id, content: out.slice(0, 8000) });
      }
    }
    msgs.push({ role: "user", content: toolResults });
  }

  // Round cap hit — ask once more for a plain answer with no further tools.
  // Same repeated system prompt as every round above, so this benefits from
  // the same cache breakpoint (see cacheSystem's doc comment).
  return askClaude(apiKey, msgs as ClaudeMessage[], opts.system, {
    model: opts.model,
    maxTokens: opts.maxTokens ?? 600,
    timeoutMs: opts.timeoutMs,
    cacheSystem: true,
  });
}
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { readTyping } from "@/lib/chat-typing";
import { readBotStep } from "@/lib/chat-bot-step";
import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";

export const runtime = "nodejs";

/**
 * Public live-chat endpoint used by <ChatWidget/>.
 *
 * POST /api/chat  — start or continue a conversation for a visitorId.
 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
 *
 * Everything is scoped strictly by the client-supplied `visitorId`; we never
 * return another visitor's data. Signed-in customers additionally get their
 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
 * POST path is rate-limited per IP.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

type AttachmentRow = { id: string; mime: string; sizeBytes: number } | null;

function serialize(convo: {
  id: string;
  status: string;
  name: string | null;
  email: string | null;
  messages: {
    id: string;
    sender: string;
    body: string;
    cardsJson?: string | null;
    createdAt: Date;
    attachment?: AttachmentRow;
  }[];
}) {
  return {
    conversation: {
      id: convo.id,
      status: convo.status,
      name: convo.name,
      email: convo.email,
    },
    messages: convo.messages.map((m) => {
      let cards: unknown = null;
      if (m.cardsJson) {
        try {
          cards = JSON.parse(m.cardsJson);
        } catch {
          cards = null;
        }
      }
      return {
        id: m.id,
        sender: m.sender,
        body: m.body,
        createdAt: m.createdAt.toISOString(),
        cards,
        attachment: m.attachment
          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
          : null,
      };
    }),
  };
}

export async function POST(req: Request) {
  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many messages. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const visitorId = clip(raw.visitorId, 100);
  const conversationId = clip(raw.conversationId, 40);
  const body = clip(raw.body, 5000);
  const name = clip(raw.name, 120);
  const email = clip(raw.email, 200);

  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });

  const user = await currentUser();
  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
    user?.id ? [{ userId: user.id }] : [],
  );

  // If the client names a conversation it owns, continue it (resuming past
  // history, reopening if it was closed). Otherwise start a brand-new one — we
  // no longer auto-resume the latest, so returning gives a fresh chat while old
  // threads stay available in the history list.
  let convo = conversationId
    ? await db.chatConversation.findFirst({
        where: { id: conversationId, OR: ownedBy },
        select: { id: true, name: true, email: true },
      })
    : null;

  if (!convo) {
    // Anonymous (not signed in) visitors must give a name + valid email before
    // starting. Signed-in customers already have both, so they're never asked.
    if (!user) {
      const nm = name ?? null;
      const em = email ?? null;
      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
        return NextResponse.json(
          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
          { status: 400 },
        );
      }
    }
    convo = await db.chatConversation.create({
      data: {
        visitorId,
        userId: user?.id ?? null,
        name: name ?? user?.name ?? null,
        email: email ?? user?.email ?? null,
      },
      select: { id: true, name: true, email: true },
    });
  }

  await db.$transaction([
    db.chatMessage.create({
      data: { conversationId: convo.id, sender: "visitor", body },
    }),
    db.chatConversation.update({
      where: { id: convo.id },
      data: {
        status: "OPEN", // reopen if the visitor is resuming a closed thread
        unreadForAgent: true,
        lastMessageAt: new Date(),
        // Backfill identity / link account if it arrives after creation.
        ...(user?.id ? { userId: user.id } : {}),
        ...(name && !convo.name ? { name } : {}),
        ...(email && !convo.email ? { email } : {}),
      },
    }),
  ]);

  // Discord bridge (Phase 1 mirror): best-effort, never blocks the visitor's
  // message — creates the guild channel on the visitor's FIRST message, posts
  // into the existing channel on every message after — see
  // lib/discord-bridge.ts's mirrorChatMessageToDiscord.
  await mirrorChatMessageToDiscord(convo.id, body, "visitor");

  // AI assistant + human-handoff orchestration (see lib/kb-run.ts). Best-effort
  // and fully wrapped: it must NEVER break live chat, and it stays silent once a
  // human has engaged.
  try {
    const { runAssistant } = await import("@/lib/kb-run");
    await runAssistant({ conversationId: convo.id, visitorId, currentBody: body });
  } catch {
    /* assistant is non-essential — never fail the visitor's message on it */
  }

  const full = await db.chatConversation.findUnique({
    where: { id: convo.id },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });
  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
}

export async function GET(req: Request) {
  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);
  const conversationId = clip(url.searchParams.get("conversationId"), 40);
  if (!visitorId) {
    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
  }

  const user = await currentUser();
  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
    user?.id ? [{ userId: user.id }] : [],
  );

  // Poll a specific conversation when named (scoped to the visitor/user), else
  // the most recent open thread for back-compat.
  let convo = conversationId
    ? await db.chatConversation.findFirst({
        where: { id: conversationId, OR: ownedBy },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      })
    : await db.chatConversation.findFirst({
        where: { visitorId, status: "OPEN" },
        orderBy: { lastMessageAt: "desc" },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      });

  if (!convo) {
    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
  }

  // If the bot is waiting on a live agent, let the poll drive the handoff window:
  // post the "no agents available" fallback once it elapses, then refresh so the
  // visitor sees it on this same poll rather than the next one.
  if (convo.botEscalatedAt) {
    try {
      const { checkEscalationTimeout } = await import("@/lib/kb-run");
      await checkEscalationTimeout(convo.id);
      const refreshed = await db.chatConversation.findFirst({
        where: { id: convo.id },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      });
      if (refreshed) convo = refreshed;
    } catch {
      /* non-essential */
    }
  }

  // Reading the thread clears the visitor-facing unread flag.
  if (convo.unreadForUser) {
    await db.chatConversation
      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
      .catch(() => {});
  }

  // The whole support transcript, plus the name/email the visitor gave. The
  // `?visitorId=` in the URL is the ONLY thing scoping it, which makes the URL
  // itself the secret — precisely the shape a shared cache must never store.
  //
  // `typing.agent` tells the widget whether a support agent is composing a reply
  // right now; it self-expires, so a stale poll can only ever under-report.
  // `botStep` is the AI agent's current live "thinking" step (e.g. "Checking
  // your billing…"), sourced from lib/chat-bot-step.ts; it self-expires too, so
  // a stalled/crashed model call can never leave a stuck label on screen.
  return NextResponse.json(
    { ...serialize(convo), typing: { agent: readTyping(convo.id).agent }, botStep: readBotStep(convo.id) },
    { headers: NO_STORE_HEADERS },
  );
}

