7	/**
8	 * LIVE plan catalogue for the AI chat agent.
9	 *
10	 * The bot used to be told plan names/sizes/prices from hand-typed strings in
11	 * lib/kb-plans.ts, lib/kb-system.ts and lib/kb-faq.ts. They drifted (it told two
12	 * customers there is no 4 GB Valheim tier, still sold the discontinued VPS Nano,
13	 * quoted stale CS2 prices, and knew only 6 of ~50 games). The facts now come from
14	 * the SAME tables the pricing pages and the deploy wizard read (Plan, GamePlan,
15	 * HostingPlan, EmailPlan) with a short cache; a small static fallback (the shapes
16	 * below, filled with a known-good snapshot) is used only if the DB read fails.
17	 *
18	 * Pure builder (`buildCatalog`) takes plain rows so tests can run without a DB.
19	 */
20	
21	export type PlanRow = { id?: string; slug: string; name: string; cpuCores: number; ramMB: number; diskGB: number; bandwidthTB: number; priceCents: number; introPriceCents?: number | null; introTermMonths?: number | null };
22	export type HostingRow = { id?: string; slug: string; name: string; priceCents: number; diskGB: number; maxSites: number; maxDatabases: number; bandwidthTB: number; mailboxes: number; freeMigration: boolean; featured: boolean };
