28	export type LiveCatalog = {
29	  cards: Record<string, PlanCard>;
30	  /** text blocks injected into the system prompt (replace the old hard-coded tier lists) */
31	  blocks: { hosting: string; vps: string; games: string; email: string };
32	  /** "key — description" lines for the [[cards: ...]] directive */
33	  keysForPrompt: string;
