43	function introLine(regular: number, intro: number | null, months: number | null): { price: number; old?: number; note?: string } {
44	  if (intro == null) return { price: regular };
45	  const span = months == null ? "first term" : months === 1 ? "first month" : `first ${months} months`;
46	  return { price: intro, old: regular, note: `${usd(intro)}/mo for the ${span}, then ${usd(regular)}/mo` };
