49	export function buildCatalog(input: CatalogInput, source: "db" | "fallback" = "db"): LiveCatalog {
50	  const cards: Record<string, PlanCard> = {};
51	  const add = (c: PlanCard) => {
52	    let key = c.key;
53	    for (let n = 2; cards[key]; n++) key = `${c.key}-${n}`;
54	    cards[key] = { ...c, key };
55	    return key;
56	  };
57	  const keyLines: string[] = [];
58	
59	  // ── Shared hosting
60	  const hostLines: string[] = [];
61	  keyLines.push("Shared hosting (managed web hosting, WordPress-ready):");
62	  for (const h of input.hosting) {
63	    const key = add({
64	      key: `shared-${h.slug}`, product: "Shared hosting", name: h.name, badge: h.featured ? "MOST POPULAR" : undefined,
65	      priceLabel: usd(h.priceCents), period: "/mo",
66	      features: [
67	        `${h.maxSites} website${h.maxSites === 1 ? "" : "s"}`,
68	        `${h.diskGB} GB NVMe storage`,
69	        `${h.maxDatabases} databases · ${h.mailboxes < 0 ? "unlimited" : h.mailboxes} mailbox${h.mailboxes === 1 ? "" : "es"}`,
70	        h.freeMigration ? "Free migration & SSL" : "Free SSL · 1-click WordPress",
71	        `${h.bandwidthTB} TB bandwidth`,
72	      ],
73	      ctaLabel: CTA, ctaUrl: deployHref({ service: "hosting", hostingPlanId: h.id }),
74	    });
75	    hostLines.push(`  ${h.name.toUpperCase()} — ${usd(h.priceCents)}/mo — ${h.diskGB} GB NVMe — ${h.maxSites} site(s) — ${h.maxDatabases} databases — ~${h.bandwidthTB} TB/mo — ${h.mailboxes} mailbox(es) — free migration: ${h.freeMigration ? "YES" : "no"}${h.featured ? " (most popular)" : ""}`);
76	    keyLines.push(`${key} — Shared hosting ${h.name} ${usd(h.priceCents)}/mo, ${h.maxSites} site(s), ${h.diskGB} GB`);
77	  }
78	
79	  // ── VPS
80	  const vpsLines: string[] = [];
81	  keyLines.push("", "VPS (full root, dedicated IPv4, NVMe; only the plans listed here exist — never mention any other VPS tier):");
82	  for (const p of input.vps) {
83	    const i = introLine(p.priceCents, planIntroMonthlyCents(p), planIntroTermMonths(p));
84	    const key = add({
85	      key: `vps-${p.slug}`, product: "VPS", name: p.name, priceLabel: usd(i.price), period: "/mo", oldPriceLabel: i.old ? usd(i.old) : undefined,
86	      features: [
