88	        "Dedicated IPv4 & full root", ...(i.note ? [i.note] : ["One-click apps · resize anytime"]),
89	      ],
90	      ctaLabel: CTA, ctaUrl: deployHref({ service: "vps", planId: p.id }),
91	    });
92	    vpsLines.push(`  ${p.name.toUpperCase()} — ${i.note ?? `${usd(p.priceCents)}/mo`} · ${p.cpuCores} vCPU · ${gbl(p.ramMB)} RAM · ${p.diskGB} GB NVMe · ${p.bandwidthTB} TB bandwidth`);
93	    keyLines.push(`${key} — VPS ${p.name} ${i.note ?? `${usd(p.priceCents)}/mo`}, ${p.cpuCores} vCPU, ${gbl(p.ramMB)} RAM`);
94	  }
95	
96	  // ── Game servers (every family, every active tier)
97	  const byFam = new Map<string, GameRow[]>();
98	  for (const g of [...input.games].sort((a, b) => a.ramMB - b.ramMB)) {
99	    byFam.set(g.gameFamily, [...(byFam.get(g.gameFamily) ?? []), g]);
100	  }
101	  const gameLines: string[] = [];
102	  keyLines.push("", "Game servers (one-click deploy, DDoS protected). Card keys: game-<game> = the featured tier; game-<game>-<N>gb = a specific tier (N = RAM in GB). The full game list with every tier is in the KNOWLEDGE BASE; call get_plans { product: 'game', game: '<name>' } for exact specs:");
