/** Pending suggestions awaiting review. Admin-gated. */
export async function listSuggestions(): Promise<SuggestionRow[]> {
  await requireArea("platform");
  const rows = await db.kbSuggestion.findMany({
    where: { status: "pending" },
    orderBy: { createdAt: "desc" },
    take: 30,
  });
  return rows.map((r) => ({
    id: r.id,
    question: r.question,
    answer: r.answer,
    category: r.category,
    status: r.status,
    createdAt: r.createdAt.toISOString(),
  }));
}

/** Approve a suggestion → it becomes a live "learned" KB entry (and survives
 *  reindex). Optionally pass an edited answer. Admin-gated. */
export async function approveSuggestion(
  id: string,
  answer?: string,
): Promise<{ ok?: boolean; error?: string }> {
  await requireArea("platform");
  const s = await db.kbSuggestion.findUnique({ where: { id } });
  if (!s) return { error: "Not found." };
  const finalAnswer = (answer ?? s.answer).trim();
  if (!finalAnswer) return { error: "Add an answer before approving." };
  try {
    await db.$transaction([
      db.kbSuggestion.update({ where: { id }, data: { status: "approved", answer: finalAnswer } }),
      db.kbChunk.create({
        data: {
          source: "learned",
          refId: `learned-${id}`,
          title: s.question,
          url: null,
          content: `${s.question}\n${finalAnswer}`,
          snippet: finalAnswer.slice(0, 340),
          category: s.category ?? "Learned",
          offer: false,
        },
      }),
    ]);
    return { ok: true };
  } catch (e) {
    return { error: e instanceof Error ? e.message : "Approve failed." };
  }
}

/** Dismiss a suggestion. Admin-gated. */
export async function rejectSuggestion(id: string): Promise<{ ok?: boolean; error?: string }> {
  await requireArea("platform");
  try {
    await db.kbSuggestion.update({ where: { id }, data: { status: "rejected" } });
    return { ok: true };
  } catch (e) {
    return { error: e instanceof Error ? e.message : "Reject failed." };
  }
}

