/**
 * Reply style + format guard for the live-chat assistant (pure, no I/O).
 *
 * The 2026-10 corpus audit (/root/agent-notes/ai-responses/AUDIT.md) found the
 * bot's real failures were mostly FORMAT, not knowledge: a median 66-word reply
 * (p90 132, max 244) where the human team's median was 11 words, numbered
 * walls of steps, raw ticket cuids, "I'd be happy to help" openers, internal
 * leaks ("the knowledge base says…", "results got cut off"), invented
 * response-time promises ("they typically respond within the hour"), and three
 * replies whose body was EMPTY (the model emitted only a [[cards]] directive).
 *
 * This module is the deterministic half of the fix:
 *   - checkReply()  → every violation, so the orchestrator can ask the model
 *                     for ONE rewrite and the eval harness can score replies;
 *   - tidyReply()   → safe mechanical cleanup (strip filler openers, sign-offs,
 *                     raw ids, stray directive fragments) that never changes a
 *                     fact;
 *   - clampReply()  → last-resort hard length cap at a sentence boundary.
 *
 * Keep it dependency-free: test/kb-style.test.ts exercises it directly.
 */

/** Hard limits. "soft" triggers a rewrite request; "hard" is never exceeded. */
export const REPLY_LIMITS = {
  softWords: 90,
  hardWords: 140,
  maxListItems: 5,
  maxLinks: 2,
  maxQuestions: 2,
} as const;

export type ReplyViolation =
  | "empty"
  | "too_long"
  | "way_too_long"
  | "long_list"
  | "too_many_links"
  | "too_many_questions"
  | "filler_opener"
  | "ai_disclaimer"
  | "sign_off"
  | "canned_closer"
  | "internal_leak"
  | "third_party_infra"
  | "fabricated_sla"
