    where: { enabled: true, status: "ONLINE" },
    select: { region: true, acceptsProvisions: true },
  });
  const open = new Map<string, boolean>();
  for (const n of nodes) open.set(n.region, (open.get(n.region) ?? false) || n.acceptsProvisions);
  const sold = [...open.entries()].filter(([, ok]) => ok).map(([r]) => customerRegionLabel(r));
