    if (r) freeByRegion.set(r, (freeByRegion.get(r) ?? 0) + p._count);
  }
  const availability = freeByRegion.size
    ? [...freeByRegion.entries()].map(([r, n]) => `${customerRegionLabel(r)}: ${n} free`).join(", ")
