function supportFact(): string {
  return [
    "SUPPORT (what the business publishes):",
    `- ${SUPPORT_REPLY_SENTENCE} That is the only response-time promise; never quote minutes or hours.`,
    "- Channels: this chat, tickets at /dashboard/support (replies there and by email), /contact, and the community Discord (https://discord.gg/hqVZdDJH2).",
