async function osFact(): Promise<string> {
  const rows = await db.osTemplate.findMany({
    where: { active: true },
    select: { name: true, version: true, category: true, licenseRequired: true },
    orderBy: [{ category: "asc" }, { sortOrder: "asc" }],
