    `- Backups: daily backups keeping the last ${BACKUP_FREE_KEEP} are included on a VPS; "Plus" keeps ${BACKUP_PLUS_KEEP} daily restore points for ${usd(backup)}/month. On-demand backups too. Backups are stored on our backup storage; don't promise off-site/geo-redundant copies.`,
    "- Add-ons are billed at full price (no first-month-free).",
  ].join("\n");
}

function hardwareFact(): string {
  return [
    "HARDWARE (what is and isn't guaranteed):",
    "- Plans are sold by vCPU count, RAM and NVMe disk. vCPUs are shared, virtualised cores, not pinned/dedicated cores, and the exact CPU model is NOT guaranteed and can differ by location and node.",
    "- Never name a CPU model, clock speed, or promise 0% CPU steal or 'dedicated cores' for a standard plan.",
    "- Dedicated/pinned CPU, bigger custom specs, Windows or bare-metal servers are custom quotes from the team: hand off with what they need (location, cores, RAM, disk, workload).",
  ].join("\n");
}

/** Execute get_platform_facts. Unknown/omitted topic → a short index. */
export async function platformFacts(input: unknown): Promise<string> {
  const raw = typeof input === "object" && input && typeof (input as { topic?: unknown }).topic === "string"
    ? (input as { topic: string }).topic.toLowerCase().trim()
    : "";
  const topic = (FACT_TOPICS as readonly string[]).includes(raw) ? (raw as FactTopic) : null;
  try {
    switch (topic) {
      case "regions":
        return await regionsFact();
      case "networking":
        return await networkingFact();
      case "refunds":
        return refundsFact();
      case "payments":
        return await paymentsFact();
      case "billing":
        return await billingFact();
      case "support":
        return supportFact();
      case "os_images":
        return await osFact();
      case "addons":
        return await addonsFact();
      case "hardware":
        return hardwareFact();
      default:
        return `Pass { topic } as one of: ${FACT_TOPICS.join(", ")}.`;
    }
  } catch (e) {
    return `Facts for "${raw}" are unavailable right now (${e instanceof Error ? e.message : "error"}). Don't guess — say a teammate will confirm, and hand off.`;
  }
}

