/**
 * Escalation + consent rules for the live-chat assistant (pure, no I/O).
 *
 * Audit findings this encodes (/root/agent-notes/ai-responses/AUDIT.md):
 *   - The old "get me a person" regex matched any message containing "agent",
 *     "rep", "someone", "live chat" or "speak to" — so "can someone tell me the
 *     price" or "is your support agent a bot?" handed off and stopped the bot.
 *     Meanwhile a bare "operator" was answered with Minecraft /op help, and
 *     non-English asks for a person ("người thật", "humano") were missed.
 *   - The bot opened tickets (written as if BY the customer) on a first message
 *     or a quick-reply chip, without asking — 7 of 15 bot-opened tickets.
 *   - Account-security and chargeback/dispute threads were argued in chat
 *     instead of going straight to a human.
 */

const norm = (s: string) => (s ?? "").toLowerCase().replace(/\s+/g, " ").trim();

/** Words that, said on their own, mean "a person please". */
const BARE_HUMAN =
  /^(?:(?:a|an|the|real|live|actual)\s+)?(?:human(?:\s+(?:being|agent|please|pls))?|person|operator|representative|rep|agent|live agent|support agent|customer (?:service|support)|staff|someone real|real person|admin)(?:\s+(?:please|pls|plz|now))?[.!?]*$/;

/** Explicit requests phrased as a sentence. */
const HUMAN_REQUEST: RegExp[] = [
  /\b(?:talk|speak|chat)\s+(?:to|with)\s+(?:a|an|the|your|some|real|actual|live)?\s*(?:human|person|people|agent|someone|somebody|staff|rep|representative|operator|manager|team ?member|employee|real person|support (?:agent|team|staff))\b/,
  /\b(?:connect|transfer|put)\s+me\s+(?:to|through to|with)\s+(?:a|an|the|your|some)?\s*(?:human|person|agent|someone|staff|rep|representative|operator|support|team|manager)\b/,
  /\b(?:get|give|find)\s+me\s+(?:a|an|some)?\s*(?:human|real person|person|agent|staff member|representative|manager)\b/,
  /\b(?:i\s+)?(?:want|need|would like|'d like|wanna)\s+(?:a|an|to talk to a|to speak to a|to speak with a|to talk with a)?\s*(?:human|real person|live agent|person|representative|manager)\b/,
  /\b(?:is there|are there|can i get)\s+(?:a|any)\s+(?:human|real person|live agent)\b/,
  /\bnot\s+(?:a|the)\s+bot\b/,
  // A few non-English asks seen or likely in this customer base.
  /\b(?:hablar con (?:un|una) (?:persona|humano|agente)|humano por favor)\b/,
  /\b(?:falar com (?:um|uma) (?:pessoa|humano|atendente))\b/,
  /\b(?:bicara dengan (?:manusia|orang|admin|cs)|minta admin)\b/,
  /(?:người thật|nhân viên hỗ trợ|gặp nhân viên)/,
  /(?:상담원|사람이랑|사람과)/,
  /(?:担当者|オペレーター|人間と話)/,
  /(?:人工客服|真人客服|转人工)/,
  /(?:gerçek (?:kişi|insan)|temsilci ile|canlı destek)/,
];

