/** Separate hidden [[cards: …]] / [[action: …]] directives from the visible
 *  text so the format check only judges what the customer actually reads. */
export function splitDirectives(text: string): { visible: string; directives: string[] } {
  const directives: string[] = [];
  const visible = (text ?? "")
    .replace(/\[\[\s*(?:cards?|action)\s*:[^\]]*\]\]/gi, (m) => {
      directives.push(m);
      return "";
    })
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return { visible, directives };
}

/**
 * Last-resort removal of whole sentences that break a hard content rule
 * (internal leak, vendor name, invented SLA, impossible follow-up promise).
 * Used only after a rewrite attempt still fails, so the customer never sees
 * the offending sentence even if the model keeps producing it.
 */
export function dropViolatingSentences(text: string): string {
  const bad = [...INTERNAL_LEAK, ...THIRD_PARTY_INFRA, ...FABRICATED_SLA, ...ASYNC_PROMISE, AI_DISCLAIMER];
  const parts = (text ?? "").split(/(?<=[.!?])\s+|\n+/);
  const kept = parts.filter((p) => !bad.some((r) => r.test(p)));
  return kept.join(" ").replace(/\s{2,}/g, " ").trim();
}
