import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/* Pure-logic checks for the reworked chat assistant (2026-10-06 audit):
 * the format guard (lib/kb-style.ts), escalation + ticket-consent rules
 * (lib/kb-escalation.ts), and the tool router's consent/dry-run gate. */

// Same server-only shim as test/chat-agent-tools.test.ts (see the comment there).
const shimDir = join(import.meta.dirname, "..", "node_modules", "server-only");
const shimIndexPath = join(shimDir, "index.js");
const OUR_SHIM = "module.exports = {};\n";
if (!existsSync(shimIndexPath) || readFileSync(shimIndexPath, "utf8") !== OUR_SHIM) {
  mkdirSync(shimDir, { recursive: true });
  writeFileSync(join(shimDir, "package.json"), '{"name":"server-only","version":"0.0.0","main":"index.js","browser":"index.js"}\n');
  writeFileSync(shimIndexPath, OUR_SHIM);
}

const style = () => import("../lib/kb-style.ts");
const esc = () => import("../lib/kb-escalation.ts");

test("a short direct answer passes the format check", async () => {
  const { checkReply } = await style();
  const r = checkReply("Valheim 4 GB (10 players) is $9.99 for the first month, then $14.38/mo. Want the 8 GB tier instead?");
  assert.deepEqual(r.violations, []);
  assert.ok(r.ok);
});

test("empty / cards-only replies are flagged", async () => {
  const { checkReply, splitDirectives } = await style();
  assert.deepEqual(checkReply("").violations, ["empty"]);
  const { visible, directives } = splitDirectives("[[cards: game-minecraft]]");
  assert.equal(visible, "");
  assert.equal(directives.length, 1);
  assert.ok(checkReply(visible).violations.includes("empty"));
});

test("length limits: soft and hard", async () => {
  const { checkReply, clampReply, REPLY_LIMITS, wordCount } = await style();
  const long = Array.from({ length: 30 }, (_, i) => `Sentence number ${i} has a few words.`).join(" ");
  const v = checkReply(long).violations;
  assert.ok(v.includes("too_long") && v.includes("way_too_long"));
  const clamped = clampReply(long);
  assert.ok(wordCount(clamped) <= REPLY_LIMITS.hardWords);
  assert.match(clamped, /\.$/, "clamped at a sentence boundary");
});

test("robotic openers, sign-offs, canned closers and AI disclaimers are caught", async () => {
  const { checkReply } = await style();
  assert.ok(checkReply("Great question! It's $2.99.").violations.includes("filler_opener"));
  assert.ok(checkReply("I'd be happy to help with that! It's $2.99.").violations.includes("filler_opener"));
  assert.ok(checkReply("It's $2.99.\n\n— Nxeon Assistant").violations.includes("sign_off"));
  assert.ok(checkReply("It's $2.99. Is there anything else I can help you with today?").violations.includes("canned_closer"));
  assert.ok(checkReply("I'm only set up to chat in English right now.").violations.includes("ai_disclaimer"));
});

test("leaks, vendor names, invented SLAs and async promises are caught", async () => {
  const { checkReply } = await style();
  assert.ok(checkReply("The knowledge base says not to quote a region.").violations.includes("internal_leak"));
  assert.ok(checkReply("(Results got cut off, but you get the idea.)").violations.includes("internal_leak"));
  assert.ok(checkReply("Our Singapore servers run on OVH.").violations.includes("third_party_infra"));
  assert.ok(checkReply("Our provider's policy covers that.").violations.includes("third_party_infra"));
  assert.ok(checkReply("They typically respond within the hour.").violations.includes("fabricated_sla"));
  assert.ok(checkReply("We guarantee 99.98% uptime.").violations.includes("fabricated_sla"));
  assert.ok(!checkReply("Our SLA targets 99.9% uptime for paid servers.").violations.includes("fabricated_sla"), "the published 99.9% target is allowed");
  assert.ok(checkReply("Let me search that. Give me a sec?").violations.includes("async_promise"));
  // Comparison pages are fine to mention.
  assert.ok(!checkReply("See /hetzner-alternative for the comparison.").violations.includes("third_party_infra"));
});

test("tidyReply strips filler and raw ids without changing facts", async () => {
  const { tidyReply, checkReply } = await style();
  const t = tidyReply("Great question! Done — ticket [cmtefq0y0004yhlozsrc5ipfz] is open at /dashboard/support.\n\n— Nxeon Assistant");
  assert.doesNotMatch(t, /cmtefq/);
  assert.doesNotMatch(t, /Great question/);
  assert.doesNotMatch(t, /Nxeon Assistant/);
  assert.match(t, /\/dashboard\/support/);
  assert.deepEqual(checkReply(t).violations, []);
});

test("dropViolatingSentences removes only the offending sentence", async () => {
  const { dropViolatingSentences } = await style();
  const out = dropViolatingSentences("Singapore is available. Our servers there run on OVH. Pick it in the wizard.");
  assert.match(out, /Singapore is available\./);
  assert.match(out, /Pick it in the wizard\./);
  assert.doesNotMatch(out, /OVH/);
});

test("humanIntent: explicit asks yes, incidental words no", async () => {
  const { humanIntent } = await esc();
  for (const yes of [
    "I'd like to talk to a human.", "operator", "human", "agent please", "real person",
    "can I speak to someone from your team", "connect me to support", "get me a human",
    "người thật", "상담원 연결해주세요", "转人工", "hablar con una persona", "canlı destek",
  ]) assert.ok(humanIntent(yes), `should hand off: ${yes}`);
  for (const no of [
    "can someone tell me the price of valheim", "is live chat open 24/7?", "how do I make my friend an operator on minecraft",
    "what does the agent field in the config do", "how much is a 4gb valheim server", "I want a refund",
  ]) assert.ok(!humanIntent(no), `should NOT hand off: ${no}`);
});

test("riskCategory routes security, disputes and legal threats", async () => {
  const { riskCategory } = await esc();
  assert.equal(riskCategory("my account got hacked"), "account_security");
  assert.equal(riskCategory("I lost my 2FA device"), "account_security");
  assert.equal(riskCategory("I'll file a chargeback with my bank"), "dispute");
  assert.equal(riskCategory("you double charged me"), "dispute");
  assert.equal(riskCategory("my lawyer will contact you"), "legal_abuse");
  assert.equal(riskCategory("can i get a refund"), null, "an ordinary refund question is answered, not escalated");
  assert.equal(riskCategory("how much is a vps"), null);
});

test("ticketConsent: explicit ask, or yes to an offer — never a chip or first message", async () => {
  const { ticketConsent } = await esc();
  assert.ok(ticketConsent("please open a ticket", null));
  assert.ok(ticketConsent("yes", "Want me to open a ticket so the team can fix it?"));
  assert.ok(ticketConsent("네", "Want me to open a ticket for the team?"));
  assert.ok(!ticketConsent("yes", "Which game are you running?"), "yes to something else isn't consent");
  assert.ok(!ticketConsent("I need technical help — something on my site or server isn't working right.", null));
  assert.ok(!ticketConsent("my server is down", "Hey! What can I help with?"));
});

test("tool router refuses an unconsented ticket and stubs writes in dry-run", async () => {
  const { runChatTool } = await import("../lib/kb-tools.ts");
  const refused = await runChatTool("user_x", "open_support_ticket", { subject: "s", body: "b" }, {
    currentMessage: "my server is down",
    previousBotMessage: null,
  });
  assert.match(refused, /NOT OPENED/);
  const dry = await runChatTool("user_x", "open_support_ticket", { subject: "Fix it", body: "b" }, {
    currentMessage: "yes please",
    previousBotMessage: "Want me to open a ticket for the team?",
    dryRun: true,
  });
  assert.match(dry, /DRY RUN/);
});

test("the assistant has the live facts + handoff tools for every visitor", async () => {
  const { chatToolsFor } = await import("../lib/kb-tools.ts");
  const names = chatToolsFor(null).map((t) => t.name);
  assert.ok(names.includes("get_platform_facts"));
  assert.ok(names.includes("hand_off_to_human"));
  assert.ok(!names.includes("open_support_ticket"), "anonymous visitors can't file tickets");
});

test("KB no longer claims every VPS has a dedicated IP or forbids naming regions", async () => {
  const { KB_SYSTEM } = await import("../lib/kb-system.ts");
  assert.doesNotMatch(KB_SYSTEM, /dedicated IP included" is literally true/);
  assert.doesNotMatch(KB_SYSTEM, /do NOT quote a specific data-center region/i);
  assert.match(KB_SYSTEM, /get_platform_facts/);
  assert.match(KB_SYSTEM, /72-hour money-back guarantee/);
  assert.doesNotMatch(KB_SYSTEM, /\bOVH\b|proxmox/i);
});

test("historyToMessages marks teammate turns and keeps roles alternating", async () => {
  const { historyToMessages } = await import("../lib/kb-llm.ts");
  const m = historyToMessages([
    { sender: "bot", body: "Hi!" },
    { sender: "visitor", body: "a" },
    { sender: "visitor", body: "b" },
    { sender: "agent", body: "It's fixed." },
    { sender: "visitor", body: "thanks" },
  ]);
  assert.equal(m[0].role, "user", "starts with the customer");
  for (let i = 1; i < m.length; i++) assert.notEqual(m[i].role, m[i - 1].role);
  assert.ok(m.some((x) => typeof x.content === "string" && x.content.startsWith("[Nxeon teammate]: It's fixed.")));
});

