/**
 * Offline replay eval for the live-chat assistant (2026-10-06 rework).
 *
 *   set -a; . /opt/nxeon/.env; set +a
 *   npx tsx scripts/ai-eval/run.ts --variant new  [--model claude-haiku-4-5] [--rules-only] [--only id1,id2]
 *   npx tsx scripts/ai-eval/run.ts --variant old  --ref main
 *
 * DRY RUN, ALWAYS: it never calls runAssistant (the only path that writes chat
 * messages, logs, tickets or emails). Every case is an ANONYMOUS visitor, so
 * no customer account is read and the account/ticket tools aren't offered;
 * the new responder additionally runs with dryRun (write tools stubbed). Reads
 * only: settings, plan tables, KbChunk search, status incidents, nodes/IP pool.
 *
 * "old" extracts lib/kb.ts, kb-llm.ts, kb-system.ts and kb-tools.ts from a git
 * ref into scripts/ai-eval/.legacy/ (gitignored) and runs that responder.
 *
 * Scoring: rule checks per case (must / mustNot regexes, expected handoff,
 * lib/kb-style.ts format check incl. 140-word hard cap) + an optional LLM judge
 * (0-2 each for correct / helpful / human-tone vs the case's ground truth).
 * Output: a JSON report in scripts/ai-eval/out/ and a summary on stdout.
 */
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

// Same server-only shim the tests use (see test/chat-agent-tools.test.ts).
const ROOT = join(import.meta.dirname, "..", "..");
const shimDir = join(ROOT, "node_modules", "server-only");
const OUR_SHIM = "module.exports = {};\n";
if (!existsSync(join(shimDir, "index.js")) || readFileSync(join(shimDir, "index.js"), "utf8") !== OUR_SHIM) {
  mkdirSync(shimDir, { recursive: true });
  writeFileSync(join(shimDir, "package.json"), '{"name":"server-only","version":"0.0.0","main":"index.js","browser":"index.js"}\n');
  writeFileSync(join(shimDir, "index.js"), OUR_SHIM);
}

type Case = {
  id: string;
  message: string;
  truth: string;
  must?: string[];
  mustNot?: string[];
  expectHandoff?: boolean;
  history?: { sender: string; body: string }[];
};
type Reply = { kind: string; text: string; error?: string; ms: number };

const args = process.argv.slice(2);
const arg = (k: string, d = "") => {
  const i = args.indexOf(`--${k}`);
  return i >= 0 && args[i + 1] && !args[i + 1].startsWith("--") ? args[i + 1] : d;
};
const flag = (k: string) => args.includes(`--${k}`);
const variant = arg("variant", "new") as "new" | "old";
const ref = arg("ref", "main");
const modelOverride = arg("model", "") || null;
const rulesOnly = flag("rules-only");
const only = arg("only", "").split(",").filter(Boolean);

function prepareLegacy(): string {
  const dir = join(ROOT, "scripts", "ai-eval", ".legacy");
  mkdirSync(dir, { recursive: true });
  const files = ["kb.ts", "kb-llm.ts", "kb-system.ts", "kb-tools.ts"];
  for (const f of files) {
    let src = execFileSync("git", ["-C", ROOT, "show", `${ref}:lib/${f}`], { encoding: "utf8" });
    for (const g of files) src = src.replaceAll(`"@/lib/${g.replace(/\.ts$/, "")}"`, `"./${g.replace(/\.ts$/, "")}"`);
    writeFileSync(join(dir, f), src);
  }
  return dir;
}

async function answerWith(c: Case): Promise<Reply> {
  const t0 = Date.now();
  const history = (c.history ?? []).map((m) => ({ role: (m.sender === "visitor" ? "user" : "assistant") as "user" | "assistant", content: m.body }));
  try {
    if (variant === "new") {
      const { kbAnswer } = await import("../../lib/kb.ts");
      const { WAIT_MSG } = await import("../../lib/kb-run.ts");
      const r = await kbAnswer(c.message, { history, userId: null, dryRun: true, modelOverride });
      // kb-run posts WAIT_MSG when a handoff carries no text of its own.
      return { kind: r.kind, text: r.reply ?? (r.kind === "handoff" ? WAIT_MSG : ""), ms: Date.now() - t0 };
    }
    const dir = prepareLegacy();
    const legacy = await import(join(dir, "kb.ts"));
    if (modelOverride) process.env.__EVAL_MODEL = modelOverride;
    const r = await legacy.kbAnswer(c.message, { history, userId: null });
    // Old kb-run posted this canned line on every handoff.
    const text = r.kind === "handoff" ? "Let me get a teammate for you — one moment while I see who's available. 👋" : r.reply ?? "";
    return { kind: r.kind, text, ms: Date.now() - t0 };
  } catch (e) {
    return { kind: "error", text: "", error: e instanceof Error ? e.message : String(e), ms: Date.now() - t0 };
  }
}

type RuleResult = { pass: boolean; failures: string[]; violations: string[]; words: number };

async function ruleScore(c: Case, r: Reply): Promise<RuleResult> {
  const { checkReply, splitDirectives } = await import("../../lib/kb-style.ts");
  const visible = splitDirectives(r.text).visible;
  const chk = checkReply(visible);
  const failures: string[] = [];
  if (r.kind === "error") failures.push(`error: ${r.error}`);
  if (r.kind === "degraded") failures.push("degraded (model unavailable)");
  const isHandoff = r.kind === "handoff";
  if (c.expectHandoff === true && !isHandoff) failures.push("expected a handoff");
  if (c.expectHandoff === false && isHandoff) failures.push("handed off when it should answer");
  if (!isHandoff || c.expectHandoff !== true) {
    for (const m of c.must ?? []) if (!new RegExp(m, "i").test(visible)) failures.push(`missing /${m}/`);
  }
  for (const m of c.mustNot ?? []) if (new RegExp(m, "i").test(visible)) failures.push(`contains /${m}/`);
  // Format rules that matter for the customer (soft length is reported, not failed).
  const hard = chk.violations.filter((v) => v !== "too_long" && v !== "too_many_questions");
  for (const v of hard) failures.push(`format: ${v}`);
  return { pass: failures.length === 0, failures, violations: chk.violations, words: chk.words };
}

type Judge = { correct: number; helpful: number; human: number; note: string } | null;

async function judge(c: Case, r: Reply): Promise<Judge> {
  if (rulesOnly || r.kind === "error") return null;
  const { askClaude } = await import("../../lib/anthropic.ts");
  const { resolveBotKey } = await import("../../lib/kb-llm.ts");
  const key = await resolveBotKey();
  if (!key) return null;
  const sys =
    "You grade a live-chat reply from a hosting company's support team. Use ONLY the ground truth to judge facts. Score each 0-2: correct (0 = states something false or invents a price/policy/feature, 1 = partly right or vague, 2 = accurate), helpful (0 = doesn't address the question, 1 = partial, 2 = answers it with the right next step), human (0 = robotic/long/filler, 1 = ok, 2 = short, direct, natural, in the customer's language). A handoff line is correct+helpful when the ground truth says to hand off. Reply with JSON only: {\"correct\":n,\"helpful\":n,\"human\":n,\"note\":\"<10 words\"}";
  const user = `Customer: ${c.message}\nGround truth: ${c.truth}\nReply: ${r.text || "(no reply)"}`;
  try {
    const out = await askClaude(key, [{ role: "user", content: user }], sys, { model: "claude-haiku-4-5", maxTokens: 120, timeoutMs: 30_000 });
    const j = JSON.parse(out.slice(out.indexOf("{"), out.lastIndexOf("}") + 1));
    return { correct: +j.correct || 0, helpful: +j.helpful || 0, human: +j.human || 0, note: String(j.note ?? "") };
  } catch {
    return null;
  }
}

async function main() {
  const cases = (JSON.parse(readFileSync(join(import.meta.dirname, "cases.json"), "utf8")) as Case[]).filter(
    (c) => !only.length || only.includes(c.id),
  );
  const rows: Array<{ id: string; reply: Reply; rules: RuleResult; judge: Judge }> = [];
  for (const c of cases) {
    const reply = await answerWith(c);
    const rules = await ruleScore(c, reply);
    const j = await judge(c, reply);
    rows.push({ id: c.id, reply, rules, judge: j });
    console.log(
      `${rules.pass ? "PASS" : "FAIL"} ${c.id.padEnd(18)} ${String(rules.words).padStart(3)}w ${reply.kind.padEnd(8)}${j ? ` judge ${j.correct}/${j.helpful}/${j.human}` : ""}${rules.failures.length ? "  — " + rules.failures.join("; ") : ""}`,
    );
  }
  const n = rows.length;
  const pass = rows.filter((r) => r.rules.pass).length;
  const words = rows.map((r) => r.rules.words).sort((a, b) => a - b);
  const judged = rows.filter((r) => r.judge);
  const avg = (k: "correct" | "helpful" | "human") => (judged.length ? judged.reduce((s, r) => s + r.judge![k], 0) / judged.length : NaN);
  const summary = {
    variant,
    ref: variant === "old" ? ref : "worktree",
    model: modelOverride ?? "(admin setting)",
    cases: n,
    rulePass: pass,
    rulePassPct: Math.round((pass / Math.max(n, 1)) * 100),
    medianWords: words[Math.floor(n / 2)] ?? 0,
    p90Words: words[Math.floor(n * 0.9)] ?? 0,
    errors: rows.filter((r) => r.reply.kind === "error" || r.reply.kind === "degraded").length,
    judge: judged.length
      ? { n: judged.length, correct: +avg("correct").toFixed(2), helpful: +avg("helpful").toFixed(2), human: +avg("human").toFixed(2), totalOf6: +(avg("correct") + avg("helpful") + avg("human")).toFixed(2) }
      : null,
  };
  console.log("\nSUMMARY", JSON.stringify(summary));
  const outDir = join(import.meta.dirname, "out");
  mkdirSync(outDir, { recursive: true });
  writeFileSync(join(outDir, `${variant}-${new Date().toISOString().replace(/[:.]/g, "-")}.json`), JSON.stringify({ summary, rows }, null, 2));
  process.exit(0);
}

main();

